<?php
declare(strict_types=1);require dirname(__DIR__,2).'/app/bootstrap.php';require dirname(__DIR__,2).'/vendor/autoload.php';
use App\Admin;use App\Security;
Admin::requirePermission('categories.view');$pdo=db();$error='';$edit=null;
if($_SERVER['REQUEST_METHOD']==='POST'){Security::requireCsrf();try{$action=(string)($_POST['action']??'');$id=(int)($_POST['id']??0);
 if($action==='save'){Admin::requirePermission('categories.manage');$name=trim((string)($_POST['name']??''));if(mb_strlen($name)<2||mb_strlen($name)>160)throw new RuntimeException('اسم القسم غير صالح.');$slug=Admin::slug((string)($_POST['slug']??$name));$desc=trim((string)($_POST['description']??''));$active=isset($_POST['is_active'])?1:0;$compliance=(string)($_POST['compliance_status']??'pending');if(!in_array($compliance,['pending','approved','rejected'],true))$compliance='pending';$sort=(int)($_POST['sort_order']??0);
 if($id){$q=$pdo->prepare("UPDATE categories SET name=?,slug=?,description=?,is_active=?,compliance_status=?,sort_order=? WHERE id=?");$q->execute([$name,$slug,$desc?:null,$active,$compliance,$sort,$id]);}else{$q=$pdo->prepare("INSERT INTO categories(name,slug,description,is_active,compliance_status,sort_order) VALUES(?,?,?,?,?,?)");$q->execute([$name,$slug,$desc?:null,$active,$compliance,$sort]);$id=(int)$pdo->lastInsertId();}Admin::audit('category.save','category',$id);header('Location: categories.php?saved=1');exit;}
 if($action==='delete'){Admin::requirePermission('categories.manage');$q=$pdo->prepare("DELETE FROM categories WHERE id=?");$q->execute([$id]);Admin::audit('category.delete','category',$id);header('Location: categories.php?deleted=1');exit;}
 }catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'تعذر حفظ العملية. تحقق من عدم تكرار رابط القسم.';}}
if(isset($_GET['edit'])){$q=$pdo->prepare("SELECT * FROM categories WHERE id=?");$q->execute([(int)$_GET['edit']]);$edit=$q->fetch()?:null;}
$rows=$pdo->query("SELECT c.*,COUNT(p.id) product_count FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.sort_order,c.id DESC")->fetchAll();
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>إدارة الأقسام | الفخامة</title><link rel="stylesheet" href="../assets/css/store.css"><style>.admin-wrap{max-width:1100px;margin:35px auto;padding:0 18px}.panel{background:#111;border:1px solid #49371c;border-radius:14px;padding:20px;margin:18px 0}.fields{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.fields label{display:block;color:#d9c49c}.fields input,.fields textarea,.fields select{width:100%;padding:10px;background:#080808;color:#fff;border:1px solid #49371c;border-radius:8px;font:inherit}.fields textarea{min-height:80px}.table{width:100%;border-collapse:collapse}.table td,.table th{text-align:right;padding:11px;border-bottom:1px solid #342718}.actions{display:flex;gap:8px}.actions form{margin:0}@media(max-width:650px){.fields{grid-template-columns:1fr}.table{font-size:12px;display:block;overflow:auto}}</style></head><body><main class="admin-wrap"><a class="text-link" href="index.php">← لوحة التحكم</a><h1>إدارة الأقسام</h1><?php if($error):?><div class="notice"><?=e($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="notice">تم حفظ القسم.</div><?php endif;?><section class="panel"><h2><?=$edit?'تعديل قسم':'إضافة قسم جديد'?></h2><form method="post"><input type="hidden" name="_csrf" value="<?=e(Security::csrfToken())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><div class="fields"><label>اسم القسم<input required name="name" maxlength="160" value="<?=e($edit['name']??'')?>"></label><label>الرابط (Slug)<input name="slug" value="<?=e($edit['slug']??'')?>" placeholder="يُنشأ تلقائياً إن تركته فارغاً"></label><label>الوصف<textarea name="description"><?=e($edit['description']??'')?></textarea></label><label>ترتيب الظهور<input type="number" name="sort_order" value="<?=(int)($edit['sort_order']??0)?>"></label><label>حالة الاعتماد<select name="compliance_status"><option value="pending">بانتظار المراجعة</option><option value="approved" <?=($edit['compliance_status']??'')==='approved'?'selected':''?>>معتمد</option><option value="rejected" <?=($edit['compliance_status']??'')==='rejected'?'selected':''?>>مرفوض</option></select></label><label><input style="width:auto" type="checkbox" name="is_active" <?=!isset($edit['is_active'])||$edit['is_active']?'checked':''?>> تفعيل القسم</label></div><p><button class="btn btn-gold">حفظ القسم</button> <a class="btn btn-outline" href="categories.php">جديد</a></p></form></section><section class="panel"><h2>الأقسام الحالية</h2><table class="table"><thead><tr><th>القسم</th><th>المنتجات</th><th>الحالة</th><th>إجراءات</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=(int)$r['product_count']?></td><td><?=e($r['compliance_status'])?> / <?=((int)$r['is_active']?'مفعل':'مخفي')?></td><td class="actions"><a class="btn btn-outline" href="?edit=<?=(int)$r['id']?>">تعديل</a><form method="post" onsubmit="return confirm('حذف القسم؟ ستبقى المنتجات دون قسم.');"><input type="hidden" name="_csrf" value="<?=e(Security::csrfToken())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn btn-outline">حذف</button></form></td></tr><?php endforeach;?></tbody></table></section></main></body></html>